const express = require('express');
const app = express();

// Resolved once at startup; falls back gracefully if package.json is unavailable.
let serverVersion = 'unknown';
try {
  serverVersion = require('./package.json').version ?? 'unknown';
} catch {
  // package.json not found or unreadable — keep the 'unknown' fallback.
}

// Required environment variables — only names are referenced here; values are
// never read, logged, or included in any response.
const REQUIRED_ENV_VARS = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'ANTHROPIC_API_KEY',
  'STRIPE_SECRET_KEY',
  'LOGFIRE_TOKEN',
];

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: serverVersion,
    uptime: process.uptime(),   // seconds since the Node process started
  });
});

// Returns 200 when all required env vars are present, 503 when any are missing.
// Only missing variable *names* are reported — values are never exposed.
app.get('/ready', (req, res) => {
  const missing = REQUIRED_ENV_VARS.filter(
    (key) => !Object.prototype.hasOwnProperty.call(process.env, key),
  );

  if (missing.length === 0) {
    return res.json({ status: 'ready' });
  }

  return res.status(503).json({
    status: 'not ready',
    missingEnvVars: missing,
  });
});

