  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: appVersion,
    uptime: process.uptime(),  // seconds since the process started
  });
});

// /ready checks that every required environment variable is present.
// Only the variable *names* are inspected — their values are never read or logged.
app.get('/ready', (req, res) => {
  const missing = REQUIRED_ENV_VARS.filter((name) => !(name in process.env));

  if (missing.length === 0) {
    return res.json({ status: 'ready', missingVars: [] });
  }

  return res.status(503).json({
    status: 'not ready',
    missingVars: missing,  // names only, never values
